<?php
namespace App\Controllers;
use App\Core\Controller;
use App\Core\Database;
use App\Core\Validator;
use App\Models\Product;
use App\Services\AuditService;
final class ProductController extends Controller {
 private Product $m; public function __construct(){ $this->m=new Product(); }
 public function index():void{$q=trim($_GET['q']??'');$cat=isset($_GET['category'])&&$_GET['category']!==''?(int)$_GET['category']:null;$page=max(1,(int)($_GET['page']??1));$data=$this->m->paginate($q,$cat,$page);$this->view('products/index',$data+['q'=>$q,'category'=>$cat,'categories'=>$this->m->categories(),'title'=>'Produits']);}
 public function createForm():void{$this->view('products/form',['product'=>null,'categories'=>$this->m->categories(),'brands'=>$this->m->brands(),'units'=>$this->m->units(),'suppliers'=>$this->m->suppliers(),'title'=>'Nouveau produit']);}
 public function store():void{$d=$this->payload();$v=(new Validator())->required('internal_code',$d['internal_code'],'Code interne')->required('name',$d['name'],'Nom')->numeric('purchase_price',$d['purchase_price'],'Prix achat')->numeric('sale_price',$d['sale_price'],'Prix vente');if($v->fails()){$_SESSION['_errors']=$v->errors();$_SESSION['_old']=$d;redirect('products/create');}$d['image']=$this->uploadImage();try{$id=$this->m->create($d);AuditService::log('CREATE','PRODUCT',null,$d);flash('success','Produit créé.');redirect('products/'.$id.'/edit');}catch(\Throwable $e){flash('error',$e->getMessage());redirect('products/create');}}
 public function editForm(string $id):void{$p=$this->m->find((int)$id);if(!$p){flash('error','Produit introuvable');redirect('products');}$this->view('products/form',['product'=>$p,'categories'=>$this->m->categories(),'brands'=>$this->m->brands(),'units'=>$this->m->units(),'suppliers'=>$this->m->suppliers(),'title'=>'Modifier produit']);}
 public function update(string $id):void{$old=$this->m->find((int)$id);$d=$this->payload();$d['image']=$this->uploadImage();$this->m->update((int)$id,$d);AuditService::log('UPDATE','PRODUCT',$old,$d);flash('success','Produit mis à jour.');redirect('products');}
 public function delete(string $id):void{$this->m->archive((int)$id);AuditService::log('ARCHIVE','PRODUCT',['id'=>$id]);flash('success','Produit archivé.');redirect('products');}
 public function searchApi():void{$q=trim($_GET['q']??'');$items=$this->m->publicList($q,null,15);$this->json(['items'=>$items]);}
 private function payload():array{return['internal_code'=>trim($_POST['internal_code']??''),'barcode'=>trim($_POST['barcode']??''),'name'=>trim($_POST['name']??''),'description'=>trim($_POST['description']??''),'category_id'=>(int)($_POST['category_id']??0),'subcategory_id'=>null,'brand_id'=>(int)($_POST['brand_id']??0),'supplier_id'=>(int)($_POST['supplier_id']??0),'unit_id'=>(int)($_POST['unit_id']??1),'purchase_price'=>(float)($_POST['purchase_price']??0),'sale_price'=>(float)($_POST['sale_price']??0),'tax_rate'=>(float)($_POST['tax_rate']??0),'min_stock'=>(float)($_POST['min_stock']??0),'max_stock'=>(float)($_POST['max_stock']??0),'location'=>trim($_POST['location']??''),'manufacturing_date'=>trim($_POST['manufacturing_date']??''),'expiration_date'=>trim($_POST['expiration_date']??''),'status'=>in_array($_POST['status']??'ACTIVE',['ACTIVE','INACTIVE'],true)?$_POST['status']:'ACTIVE','image'=>null];}
 private function uploadImage():?string{if(empty($_FILES['image']['tmp_name']))return null;$f=$_FILES['image'];if($f['size']>2*1024*1024)throw new \RuntimeException('Image trop volumineuse (2 Mo max).');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new \RuntimeException('Format image non autorisé.');$name='prod-'.bin2hex(random_bytes(8)).'.'.$ext;$dest=dirname(__DIR__,2).'/public/uploads/products/'.$name;if(!move_uploaded_file($f['tmp_name'],$dest))throw new \RuntimeException('Échec upload image.');return'products/'.$name;}

 public function label(string $id):void{$p=$this->m->find((int)$id);if(!$p){redirect('products');}$this->view('products/label',['product'=>$p,'title'=>'Étiquette '.$p['name']],false);}

 public function exportCsv():never{$db=Database::connection();$rows=$db->query("SELECT p.internal_code,p.barcode,p.name,c.name category,b.name brand,u.symbol unit,p.purchase_price,p.sale_price,s.quantity,p.min_stock,p.max_stock,p.location,p.expiration_date,p.status FROM products p JOIN categories c ON c.id=p.category_id JOIN units u ON u.id=p.unit_id LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN stocks s ON s.product_id=p.id WHERE p.status<>'ARCHIVED' ORDER BY p.name")->fetchAll();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="produits_kinmart.csv"');$o=fopen('php://output','w');fputcsv($o,['internal_code','barcode','name','category','brand','unit','purchase_price','sale_price','quantity','min_stock','max_stock','location','expiration_date','status'],';');foreach($rows as $r)fputcsv($o,array_values($r),';');fclose($o);exit;}
 public function importCsv():void{if(empty($_FILES['csv']['tmp_name'])){flash('error','Sélectionnez un fichier CSV.');redirect('products');}$f=$_FILES['csv'];if($f['size']>5*1024*1024){flash('error','CSV trop volumineux.');redirect('products');}$h=fopen($f['tmp_name'],'r');if(!$h){flash('error','Lecture CSV impossible.');redirect('products');}$header=fgetcsv($h,0,';');if(!$header){fclose($h);flash('error','CSV vide.');redirect('products');}$map=array_flip(array_map('trim',$header));$required=['internal_code','name','category','purchase_price','sale_price'];foreach($required as $k)if(!isset($map[$k])){fclose($h);flash('error','Colonne manquante: '.$k);redirect('products');}$db=Database::connection();$count=0;try{Database::transaction(function($db)use($h,$map,&$count){while(($row=fgetcsv($h,0,';'))!==false){$get=fn($k,$d='')=>trim((string)($row[$map[$k]??-1]??$d));$code=$get('internal_code');$name=$get('name');if($code===''||$name==='')continue;$catName=$get('category','Alimentation');$st=$db->prepare("SELECT id FROM categories WHERE name=? LIMIT 1");$st->execute([$catName]);$cat=(int)($st->fetchColumn()?:1);$brand=null;if($get('brand')!==''){$b=$db->prepare("SELECT id FROM brands WHERE name=? LIMIT 1");$b->execute([$get('brand')]);$brand=$b->fetchColumn()?:null;}$unit=1;if($get('unit')!==''){$u=$db->prepare("SELECT id FROM units WHERE symbol=? OR name=? LIMIT 1");$u->execute([$get('unit'),$get('unit')]);$unit=(int)($u->fetchColumn()?:1);}$exists=$db->prepare("SELECT id FROM products WHERE internal_code=?");$exists->execute([$code]);$pid=$exists->fetchColumn();if($pid){$db->prepare("UPDATE products SET barcode=?,name=?,category_id=?,brand_id=?,unit_id=?,purchase_price=?,sale_price=?,min_stock=?,max_stock=?,location=?,expiration_date=?,status=? WHERE id=?")->execute([$get('barcode')?:null,$name,$cat,$brand,$unit,(float)$get('purchase_price',0),(float)$get('sale_price',0),(float)$get('min_stock',5),(float)$get('max_stock',100),$get('location')?:null,$get('expiration_date')?:null,$get('status','ACTIVE'),$pid]);}else{$db->prepare("INSERT INTO products(internal_code,barcode,name,category_id,brand_id,unit_id,purchase_price,sale_price,min_stock,max_stock,location,expiration_date,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$code,$get('barcode')?:null,$name,$cat,$brand,$unit,(float)$get('purchase_price',0),(float)$get('sale_price',0),(float)$get('min_stock',5),(float)$get('max_stock',100),$get('location')?:null,$get('expiration_date')?:null,$get('status','ACTIVE')]);$pid=(int)$db->lastInsertId();$db->prepare("INSERT INTO stocks(product_id,quantity) VALUES(?,?)")->execute([$pid,(float)$get('quantity',0)]);}if($pid&&$get('quantity')!=='')$db->prepare("UPDATE stocks SET quantity=? WHERE product_id=?")->execute([(float)$get('quantity',0),$pid]);$count++;}});fclose($h);AuditService::log('IMPORT','PRODUCT',null,['rows'=>$count]);flash('success',$count.' produit(s) importé(s)/mis à jour.');}catch(\Throwable $e){fclose($h);flash('error','Import interrompu: '.$e->getMessage());}redirect('products');}
}
